package com.tecsup.pedido.service; import com.tecsup.pedido.dto.PedidoRequest; import com.tecsup.pedido.model.*; import com.tecsup.pedido.repository.PedidoRepository; import java.math.BigDecimal; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import org.springframework.web.server.ResponseStatusException;
@Service public class PedidoService {private final PedidoRepository repo;private final RestClient clientes,productos;public PedidoService(PedidoRepository r,RestClient.Builder b,@Value("${pedido.url-clientes}")String c,@Value("${pedido.url-productos}")String p){repo=r;clientes=b.clone().baseUrl(c).build();productos=b.clone().baseUrl(p).build();}
public List<Pedido> listar(){return repo.findAll();}public Pedido obtener(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Pedido no encontrado"));}
private Pedido nuevo(PedidoRequest d){try{clientes.get().uri("/api/clientes/{id}",d.idCliente()).retrieve().toBodilessEntity();}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Cliente no disponible");}Pedido p=new Pedido();p.setFecha(d.fecha());p.setIdCliente(d.idCliente());BigDecimal total=BigDecimal.ZERO;List<DetallePedido> lines=new ArrayList<>();for(var x:d.detalles()){try{productos.get().uri("/api/productos/{id}",x.idProducto()).retrieve().toBodilessEntity();}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Producto no disponible: "+x.idProducto());}DetallePedido l=new DetallePedido();l.setIdProducto(x.idProducto());l.setCantidad(x.cantidad());l.setPrecio(x.precio());l.setPedido(p);lines.add(l);total=total.add(x.precio().multiply(BigDecimal.valueOf(x.cantidad())));}p.setDetalles(lines);p.setTotal(total);return p;}
public Pedido crear(PedidoRequest d){return repo.save(nuevo(d));}public Pedido actualizar(Long id,PedidoRequest d){Pedido old=obtener(id);Pedido n=nuevo(d);old.setFecha(n.getFecha());old.setIdCliente(n.getIdCliente());old.setTotal(n.getTotal());old.getDetalles().clear();for(DetallePedido l:n.getDetalles()){l.setPedido(old);old.getDetalles().add(l);}return repo.save(old);}public void eliminar(Long id){repo.delete(obtener(id));}}
